"""Numeral 1.2.2: discrepancy P and documented-scenario Q error propagation.
No original inputs are edited. Q scenarios are not Racarumi measurements.
"""
from pathlib import Path
import json, platform
import numpy as np
import pandas as pd
import matplotlib.pyplot as plt
ROOT=next(p for p in Path(__file__).resolve().parents if (p / "codigo").is_dir() and (p / "datos").is_dir())
T1=ROOT/'datos'/'punto1'/'originales'/'tarea1_minimos'
MASTER=T1/'PE_200907_master_monthly.csv'
PACHO=ROOT/'datos/punto1/originales/1_2_balance_hidrico/Racarumi_balance_anual_2001_2023.csv'
CODE=ROOT/'codigo/punto1/1_2_evapotranspiracion_real/02_propagacion_error'; OUT=ROOT/'datos/punto1/procesados/1_2_2_propagacion_error'; META=ROOT/'datos/punto1/metadatos'; TAB=ROOT/'productos/punto1/1_2_evapotranspiracion_real/tablas'; FIG=ROOT/'productos/punto1/1_2_evapotranspiracion_real/figuras'; ANN=ROOT/'anexos/punto1/1_2_2_propagacion_error'
for p in [CODE,OUT,META,TAB,FIG,ANN]:p.mkdir(parents=True,exist_ok=True)
def hy(x):return x.dt.year+(x.dt.month>=9).astype(int)
def metrics(x,y):
 d=y-x
 return {'n':int(d.notna().sum()),'bias_PI_minus_PL_mm':float(d.mean()),'sd_difference_mm':float(d.std(ddof=1)),'MAE_mm':float(d.abs().mean()),'RMSE_mm':float(np.sqrt(np.mean(d.dropna()**2))),'Pearson':float(x.corr(y,'pearson')),'Spearman':float(x.rank().corr(y.rank(),'pearson')),'mean_relative_difference_PI_minus_PL_pct':float((100*d/x).mean())}
def figsave(f,n):
 for z in ['png','pdf']:f.savefig(FIG/f'{n}.{z}',dpi=180)
 plt.close(f)

# 1) Original monthly comparison; no imputation, only months jointly available.
m=pd.read_csv(MASTER,parse_dates=['date']);m=m.loc[m.camels_precip_complete.astype(bool)&m.imerg_complete.astype(bool),['date','camels_precip_mm_month','imerg_precip_mm_month']].dropna().copy();m=m.rename(columns={'camels_precip_mm_month':'PL_mm_mes','imerg_precip_mm_month':'PI_mm_mes'});m['difference_PI_minus_PL_mm']=m.PI_mm_mes-m.PL_mm_mes;m['relative_difference_pct']=100*m.difference_PI_minus_PL_mm/m.PL_mm_mes;m['calendar_month']=m.date.dt.month;m['hydro_year']=hy(m.date)
month_stats=metrics(m.PL_mm_mes,m.PI_mm_mes);month_stats['period']=f'{m.date.min():%Y-%m} to {m.date.max():%Y-%m}';month_stats['n_expected_reference']=279
m.to_csv(OUT/'1_2_2_diferencias_mensuales_PL_PI.csv',index=False)
season=m.groupby('calendar_month',as_index=False).agg(PL_mm_mes=('PL_mm_mes','mean'),PI_mm_mes=('PI_mm_mes','mean'),difference_mean_mm=('difference_PI_minus_PL_mm','mean'),difference_sd_mm=('difference_PI_minus_PL_mm','std'),MAE_mm=('difference_PI_minus_PL_mm',lambda s:s.abs().mean()),n=('date','count'));season['mes']=['Ene','Feb','Mar','Abr','May','Jun','Jul','Ago','Sep','Oct','Nov','Dic'];season.to_csv(TAB/'1_2_2_estacionalidad_discrepancia_PL_PI.csv',index=False)
# 2) Pacho annual inputs; keep incomplete-Q years visible.
a=pd.read_csv(PACHO);cols=['anio_hidrologico','PL_mm_anio','PI_mm_anio','Q_mm_anio','PL_menos_Q_mm_anio','PI_menos_Q_mm_anio'];a=a[cols].copy();a['difference_PI_minus_PL_mm']=a.PI_mm_anio-a.PL_mm_anio;a['relative_difference_pct']=100*a.difference_PI_minus_PL_mm/a.PL_mm_anio;a['q_complete']=a.Q_mm_anio.notna();a['negative_PI_minus_Q']=a.PI_menos_Q_mm_anio<0
ann_all=metrics(a.PL_mm_anio,a.PI_mm_anio);common=a.loc[a.q_complete].copy();ann_common=metrics(common.PL_mm_anio,common.PI_mm_anio);ann_all.update({'n_years':len(a),'n_q_complete':len(common),'missing_Q_years':a.loc[~a.q_complete,'anio_hidrologico'].astype(int).tolist(),'negative_PI_minus_Q_years':a.loc[a.negative_PI_minus_Q,'anio_hidrologico'].astype(int).tolist()})
# σP is proxy of between-product dispersion, not a single-source instrument error.
sigma_p=float(common.difference_PI_minus_PL_mm.std(ddof=1));bias_p=float(common.difference_PI_minus_PL_mm.mean());rmse_p=float(np.sqrt(np.mean(common.difference_PI_minus_PL_mm**2)))
qsc={'lower_10pct_bound':.10,'main_15pct_bound':.15,'upper_20pct_bound':.20}
for name,bound in qsc.items():
 s=bound/1.96
 for source in ['PL','PI']:
  etcol=f'{source}_menos_Q_mm_anio';pcol=f'{source}_mm_anio';a[f'sigmaP_{source}_interproductSD_mm']=sigma_p;a[f'sigmaQ_{name}_mm']=s*a.Q_mm_anio;a[f'sigmaET_{source}_{name}_mm']=np.sqrt(sigma_p**2+a[f'sigmaQ_{name}_mm']**2);a[f'relative_sigmaET_{source}_{name}_pct']=np.where(a[etcol]>a[f'sigmaET_{source}_{name}_mm'],100*a[f'sigmaET_{source}_{name}_mm']/a[etcol],np.nan);a[f'P_variance_fraction_{source}_{name}']=sigma_p**2/a[f'sigmaET_{source}_{name}_mm']**2
a.to_csv(OUT/'1_2_2_balance_anual_y_propagacion_por_escenario.csv',index=False)
# Summary per source and scenario; multiyear retains systematic/interproduct spread.
summary=[]
for source in ['PL','PI']:
 et=f'{source}_menos_Q_mm_anio';p=f'{source}_mm_anio'
 for scenario,bound in qsc.items():
  r=bound/1.96; sigq=r*common.Q_mm_anio.mean(); siget=np.sqrt(sigma_p**2+sigq**2); etmean=common[et].mean();ok=etmean>siget
  summary.append({'precipitation_source':source,'scenario_Q':scenario,'Q_bound_assumed_pct':100*bound,'sigmaQ_as_percent_of_Q':100*r,'n_complete_years':len(common),'P_mean_mm_year':common[p].mean(),'Q_mean_mm_year':common.Q_mm_anio.mean(),'ET_balance_mean_mm_year':etmean,'precip_difference_bias_PI_minus_PL_mm_year':bias_p,'sigmaP_interproduct_dispersion_mm_year':sigma_p,'RMSE_interproduct_mm_year':rmse_p,'sigmaQ_mm_year':sigq,'sigmaET_mm_year':siget,'ET_relative_uncertainty_pct':100*siget/etmean if ok else np.nan,'P_variance_fraction_pct':100*sigma_p**2/siget**2,'Q_variance_fraction_pct':100*sigq**2/siget**2,'interpretability':'interpretable' if ok else 'not interpretable: ET balance <= propagated 1-sigma'})
S=pd.DataFrame(summary);S.to_csv(TAB/'1_2_2_resumen_propagacion_error_principal.csv',index=False)
# Dry/wet precipitation difference; annually aggregated directly, not monthly RMSE scaled.
q1,q2=common.PL_mm_anio.quantile([1/3,2/3]);common['PL_class']=pd.cut(common.PL_mm_anio,[-np.inf,q1,q2,np.inf],labels=['dry','normal','wet'],include_lowest=True);drywet=common.groupby('PL_class',observed=False).agg(n=('anio_hidrologico','count'),PL_mean=('PL_mm_anio','mean'),PI_mean=('PI_mm_anio','mean'),PI_minus_PL_mean=('difference_PI_minus_PL_mm','mean'),PI_minus_PL_sd=('difference_PI_minus_PL_mm','std'));drywet.to_csv(TAB/'1_2_2_discrepancia_PL_PI_anios_secos_humedos.csv')
# Bootstrap describes sampling variation of difference, not instrumental uncertainty.
rng=np.random.default_rng(20261121);vals=common.difference_PI_minus_PL_mm.to_numpy();boot=np.array([rng.choice(vals,len(vals),replace=True).mean() for _ in range(10000)]);bootinfo={'n_resamples':10000,'seed':20261121,'bias_PI_minus_PL_mm_year':bias_p,'bootstrap95_low_mm_year':float(np.quantile(boot,.025)),'bootstrap95_high_mm_year':float(np.quantile(boot,.975)),'limitation':'i.i.d. annual bootstrap; does not quantify instrumental uncertainty or serial/common-mode errors.'}
# Manual verification year, with main scenario and explicit equation substitution.
v=common.loc[common.anio_hidrologico.eq(2002)].iloc[0];rq=qsc['main_15pct_bound']/1.96;vq=rq*v.Q_mm_anio;vet=np.sqrt(sigma_p**2+vq**2);manual={'year':2002,'PL_mm':float(v.PL_mm_anio),'PI_mm':float(v.PI_mm_anio),'Q_mm':float(v.Q_mm_anio),'ET_PL_mm':float(v.PL_menos_Q_mm_anio),'ET_PI_mm':float(v.PI_menos_Q_mm_anio),'sigmaP_proxy_mm':sigma_p,'sigmaQ_main_mm':float(vq),'sigmaET_main_mm':float(vet),'equation':'sigmaET=sqrt(sigmaP^2+sigmaQ^2); ET=P-Q','units_check':'all terms mm per hydrological year; variances mm² per hydrological year²'}
(ANN/'1_2_2_verificacion_manual_2002.json').write_text(json.dumps(manual,ensure_ascii=False,indent=2),encoding='utf8')
qc={'monthly_comparison':month_stats,'annual_all':ann_all,'annual_common':ann_common,'sigmaP_definition':'SD of annual (PI−PL) for 21 Q-complete years; indirect between-product discrepancy proxy, not PL or PI instrument sigma.','Q_scenarios':'Benchmark bounds ±10/±15/±20% converted to approximate 1-sigma by dividing 1.96; hypothetical for Racarumi, not station-specific.','independence':'Primary propagation assumes independent P and Q measurement errors; observed P-Q covariance is not substituted for measurement-error covariance.','multiyear':'No 1/sqrt(n) reduction is applied in principal summary because rating/discrepancy components may be systematic or temporally dependent.','duplicates_annual':int(a.anio_hidrologico.duplicated().sum()),'units':'mm per hydrological year','dependencies':{'python':platform.python_version(),'numpy':np.__version__,'pandas':pd.__version__,'matplotlib':plt.matplotlib.__version__}}
(META/'1_2_2_control_calidad_y_metadatos.json').write_text(json.dumps(qc,ensure_ascii=False,indent=2),encoding='utf8');(ANN/'1_2_2_bootstrap_discrepancia_P.json').write_text(json.dumps(bootinfo,ensure_ascii=False,indent=2),encoding='utf8')
# Figures.
plt.style.use('seaborn-v0_8-whitegrid');fig,ax=plt.subplots(figsize=(9,4));ax.plot(a.anio_hidrologico,a.PL_mm_anio,'o-',label='PL');ax.plot(a.anio_hidrologico,a.PI_mm_anio,'o-',label='PI');ax.set(xlabel='Año hidrológico',ylabel='mm/año',title='Precipitación anual: PL e IMERG');ax.legend();figsave(fig,'1_2_2_PL_PI_anual')
fig,ax=plt.subplots(figsize=(9,4));ax.axhline(0,color='k',lw=.8);ax.bar(a.anio_hidrologico,a.difference_PI_minus_PL_mm,color=np.where(a.difference_PI_minus_PL_mm<0,'#d1495b','#2a9d8f'));ax.set(xlabel='Año hidrológico',ylabel='PI − PL (mm/año)',title='Discrepancia anual entre productos de precipitación');figsave(fig,'1_2_2_diferencia_anual_PI_menos_PL')
fig,ax=plt.subplots(figsize=(9,4));ax.plot(common.anio_hidrologico,common.PL_menos_Q_mm_anio,'o-',label='P_L − Q');ax.plot(common.anio_hidrologico,common.PI_menos_Q_mm_anio,'o-',label='P_I − Q');ax.axhline(0,color='k',lw=.8);ax.set(xlabel='Año hidrológico',ylabel='mm/año',title='ET de balance exploratoria');ax.legend();figsave(fig,'1_2_2_ET_balance_PL_PI')
main=a.loc[a.q_complete].copy();fig,ax=plt.subplots(figsize=(9,4));ax.errorbar(main.anio_hidrologico,main.PL_menos_Q_mm_anio,yerr=main.sigmaET_PL_main_15pct_bound_mm,fmt='o',label='PL−Q ±σ');ax.errorbar(main.anio_hidrologico,main.PI_menos_Q_mm_anio,yerr=main.sigmaET_PI_main_15pct_bound_mm,fmt='o',label='PI−Q ±σ');ax.axhline(0,color='k',lw=.8);ax.set(xlabel='Año hidrológico',ylabel='mm/año',title='ET exploratoria y propagación independiente');ax.legend();figsave(fig,'1_2_2_ET_anual_barras_incertidumbre')
fig,ax=plt.subplots(figsize=(7,4));z=S.loc[S.scenario_Q.eq('main_15pct_bound')];ax.bar(z.precipitation_source,z.P_variance_fraction_pct,label='P');ax.bar(z.precipitation_source,z.Q_variance_fraction_pct,bottom=z.P_variance_fraction_pct,label='Q');ax.set(ylabel='% de varianza propagada',title='Contribución a varianza de ET');ax.legend();figsave(fig,'1_2_2_contribucion_varianza_P_Q')
fig,ax=plt.subplots(figsize=(7,4));
for src,g in S.groupby('precipitation_source'):ax.plot(g.Q_bound_assumed_pct,g.sigmaET_mm_year,'o-',label=src)
ax.set(xlabel='Límite hipotético de incertidumbre Q (%)',ylabel='σET (mm/año)',title='Sensibilidad de ET a incertidumbre de caudal');ax.legend();figsave(fig,'1_2_2_sensibilidad_Q')
fig,ax=plt.subplots(figsize=(7,4));
for src,g in S.groupby('precipitation_source'):ax.plot(g.Q_bound_assumed_pct,g.ET_relative_uncertainty_pct,'o-',label=src)
ax.set(xlabel='Límite hipotético de incertidumbre Q (%)',ylabel='100 σET / ET (%)',title='Fracción de incertidumbre respecto a ET');ax.legend();figsave(fig,'1_2_2_incertidumbre_relativa_ET')
refs=['# Referencias verificadas para escenarios de Q','','- McMillan, H. K. et al. (2012), *How uncertainty analysis of streamflow data can reduce costs and promote robust decisions in water management applications*, Water Resources Research, doi:10.1002/2016WR020328. Reporta bandas típicas ±10–20 % para caudales medios–altos dentro de cauce; su aplicabilidad a Racarumi no está demostrada.','- Westerberg, I. K. & McMillan, H. K. (2015), *Uncertainty in hydrological signatures*, Hydrology and Earth System Sciences, 19, 3951–3968. https://doi.org/10.5194/hess-19-3951-2015. Tabla 3: la incertidumbre de curva de gasto domina varias firmas.','- Coxon, G. et al. (2015), *A novel framework for discharge uncertainty quantification applied to 500 UK gauging stations*, Water Resources Research, doi:10.1002/2014WR016532. La incertidumbre es específica del sitio, depende de curva de gasto, aforos y condiciones hidráulicas.','- Llauca et al. (2026), CAMELS-PE, https://doi.org/10.5194/essd-2026-386. Para Racarumi, CAMELS-PE identifica `flow_obs` como caudal observado de SENAMHI; no suministra incertidumbre cuantificada de su curva de gasto.']
(ANN/'1_2_2_referencias_incertidumbre_caudal.md').write_text('\n'.join(refs)+'\n',encoding='utf8')
report=['# 1.2.2 — resumen para Pacho','','## Resultado principal','La diferencia entre PL y PI contiene sesgo sistemático y dispersión entre productos. No se interpreta PL como verdad ni la discrepancia como error aleatorio puro.','',f"En los {len(common)} años con Q completo: sesgo PI−PL = {bias_p:.2f} mm/año; σP proxy (DE de PI−PL) = {sigma_p:.2f} mm/año; RMSE interproducto = {rmse_p:.2f} mm/año.",'','El escenario principal para Q es una banda hipotética ±15 % convertida a σQ/Q=7.65 %, basada en literatura de incertidumbre de curva de gasto para caudal medio–alto. No es una incertidumbre medida en Racarumi.','','La síntesis principal usa σET=sqrt(σP²+σQ²), con independencia de errores. La covarianza de errores es desconocida; la correlación observada P–Q no la reemplaza. No se reduce la incertidumbre multianual por sqrt(n) debido a componentes potencialmente sistemáticos/dependientes.','','Los balances PI−Q negativos (2009, 2012, 2019, 2021, 2022) se mantienen como evidencia de limitación de los insumos y no representan ET negativa.','','## Pendiente para resultado definitivo','Curva de gasto/aforos y evaluación de incertidumbre específica de Racarumi; ET de productos 1.2; evidencia de ΔS anual, regulación, aportes, transferencias y extracciones.']
(ANN/'1_2_2_resumen_resultados_para_pacho.md').write_text('\n'.join(report)+'\n',encoding='utf8')
inv={'script':'codigo/punto1/1_2_evapotranspiracion_real/02_propagacion_error/run_1_2_2_propagacion_error.py','tables':[x.name for x in TAB.glob('1_2_2*')],'figures':[x.name for x in FIG.glob('1_2_2*')],'status':'PRELIMINAR: Q uncertainty is literature-based scenario, not Racarumi-specific.'};(ANN/'1_2_2_inventario_productos.json').write_text(json.dumps(inv,ensure_ascii=False,indent=2),encoding='utf8')
compliance=['# Cumplimiento — 1.2.2 propagación del error','','| Exigencia | Estado | Evidencia |','|---|---|---|','| Diferencia PL–PI mensual/anual | COMPLETADO | Series, estacionalidad y estadísticas directas |','| Sesgo transmitido a ET=P−Q | COMPLETADO | Tabla anual conserva PI−Q negativos |','| Incertidumbre Q documentada | PRELIMINAR | Escenarios bibliográficos; no hay curva de gasto de Racarumi |','| Propagación independiente | COMPLETADO (escenario) | σET²=σP²+σQ² |','| Covarianza de errores | PENDIENTE | No se inventó Cov(errorP,errorQ) |','| Fracción respecto a ET | COMPLETADO con condición | Se oculta cuando ET≤σET |','| Verificación manual/unidades | COMPLETADO | Año 2002, anexo JSON |','| Bootstrap | COMPLETADO como sensibilidad | No se interpreta como incertidumbre instrumental |','| Resultado definitivo | PENDIENTE POR DATOS | Requiere incertidumbre Q local y cierre de almacenamiento |']
(ANN/'1_2_2_estado_cumplimiento.md').write_text('\n'.join(compliance)+'\n',encoding='utf8')
print(json.dumps({'monthly':month_stats,'annual_all':ann_all,'annual_common':ann_common,'summary':S.to_dict(orient='records'),'manual':manual},ensure_ascii=False,indent=2))
